int removeDuplicates(vector<int>& nums) {
    int w = 0;
    for (int x : nums) {
        if (w < 2 || x != nums[w - 2]) nums[w++] = x;   // keep unless it would be a third copy
    }
    return w;
}

public int removeDuplicates(int[] nums) {
    int w = 0;
    for (int x : nums) {
        if (w < 2 || x != nums[w - 2]) nums[w++] = x;   // keep unless it would be a third copy
    }
    return w;
}
